// inspired by PZ's https://www.shadertoy.com/view/Ms3yzS
// reference: https://www.gamedev.net/articles/programming/graphics/advanced-terrain-texture-splatting-r3287/

void mainImage( out vec4 O, vec2 U )
{
    U /= iResolution.xy;

    vec4 T0  = texture(iChannel0,U*4.).rrrr, // boulders - mushrooms
         T0z = T0, 
         T1  = texture(iChannel1,U),         // wood - ground
         T1z = textureLod(iChannel1,U,6.),
         T2 = texture(iChannel2,U);          // noise - moss

    float v0 = length(T0z.rgb)/3. *2.-1.,    // centered pseudo Z-values
          v1 = length(T1z.rgb)/3. *2.-1.,
          x =  2.*U.x - 1.;

    v1 = 6.*v1+1.0;                          // amplify and uplift ground

    float strength1 = 1.,
              mask1 = .5 + strength1* ( v1-v0 - 1.2*x ), // mushrooms/ground
          strength2 = 2.,
              mask2 = .5 + strength2 * ( v0 - (-.7));    // mushrooms/moss

    T0 = mix( T2.x*vec4(0.224,0.000,0.502,0),           // mushrooms over moss
              T0*vec4(1 ,.9,1 ,0),
              clamp( mask2, 0., 1. )
             );
    O = mix( T0*vec4(1 ,.9,1 ,0),            // mushroom on ground valleys
             T1*vec4(0.341,0.682,1.000,0), 
             clamp( mask1, 0., 1. )
           );
}

